class Solution {
public:
    long long fixedRatio(string s, int num1, int num2) {
        unordered_map<long long, long long> freq;
        freq[0] = 1;
        long long balance = 0, answer = 0;
        for (char c : s) {
            balance += c == '0' ? num2 : -num1;
            answer += freq[balance];
            ++freq[balance];
        }
        return answer;
    }
};
